import java.util.Arrays;

class MyClass {
    private String[] names;
    private int[] ids;
    private java.util.List<String> items;

    public MyClass(String[] names, int[] ids, java.util.List<String> items) {
        this.names = names;
        this.ids = ids;
        this.items = items;
    }

    @Override
    public int hashCode() {
        final int prime = 31;
        int result = 1;
        result = prime * result + (names == null ? 0 : java.util.Arrays.hashCode(names)); // Transformed
        result = prime * result + (ids == null ? 0 : java.util.Arrays.hashCode(ids)); // Transformed
        result = prime * result + (items == null ? 0 : items.hashCode()); // Untouched
        return result;
    }
}

