class NonArrayTest {
    private String name;
    private java.util.List<String> collection;

    public NonArrayTest(String name, java.util.List<String> collection) {
        this.name = name;
        this.collection = collection;
    }

    @Override
    public int hashCode() {
        // Should NOT match 'name.hashCode()' because String is not an array type.
        // Its hashCode() is already content-based.
        // Should NOT match 'collection.hashCode()' because List is not an array type.
        return name.hashCode() + collection.hashCode();
    }
}
